BEGIN;
CREATE TABLE IF NOT EXISTS marketing_forms(id SERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,slug VARCHAR(160) NOT NULL UNIQUE,form_type VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','archived')),current_version INTEGER NOT NULL DEFAULT 1,created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS marketing_form_versions(id BIGSERIAL PRIMARY KEY,form_id INTEGER NOT NULL REFERENCES marketing_forms(id) ON DELETE CASCADE,version INTEGER NOT NULL,field_schema JSONB NOT NULL DEFAULT '[]',hidden_fields JSONB NOT NULL DEFAULT '{}',consent_config JSONB NOT NULL DEFAULT '{}',success_message VARCHAR(500),redirect_url TEXT,campaign_id INTEGER REFERENCES campaigns(id) ON DELETE SET NULL,created_at TIMESTAMP DEFAULT NOW(),UNIQUE(form_id,version));
CREATE TABLE IF NOT EXISTS marketing_form_submissions(id BIGSERIAL PRIMARY KEY,form_version_id BIGINT NOT NULL REFERENCES marketing_form_versions(id) ON DELETE RESTRICT,marketing_contact_id INTEGER REFERENCES marketing_contacts(id) ON DELETE SET NULL,visitor_id VARCHAR(64),session_id VARCHAR(64),data JSONB NOT NULL,utm JSONB NOT NULL DEFAULT '{}',consent JSONB NOT NULL DEFAULT '{}',submitted_at TIMESTAMP DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_mkt_form_submissions_form ON marketing_form_submissions(form_version_id,submitted_at DESC);
COMMIT;
